import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import AddCameraModal from './AddCameraModal';

function AnimatedNumber({ value, color }) {
  const [display, setDisplay] = useState(value);

  useEffect(() => {
    setDisplay(value);
  }, [value]);

  return (
    <div style={{
      fontSize:   20,
      fontWeight: 700,
      color,
      lineHeight: 1.1,
      transition: 'color .3s'
    }}>
      {display}
    </div>
  );
}

export default function StatsRow() {
  const { stats, wsConnected } = useApp();
  const [showModal, setShowModal] = useState(false);

  const items = [
    {
      icon:     '📷',
      label:    'Cameras',
      value:    `${stats.cameras_online || 0} / ${stats.cameras_total || 0}`,
      sub:      'Online',
      subColor: '#3b82f6',
      onClick:  null
    },
    {
      icon:     '🔍',
      label:    'Total Detections',
      value:    stats.total_detections || 0,
      sub:      'Today',
      subColor: '#64748b',
      onClick:  null
    },
    {
      icon:     '🚨',
      label:    'Active Alerts',
      value:    stats.active_alerts || 0,
      sub:      'View All',
      subColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#64748b',
      valColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#22c55e',
      onClick:  () => window.dispatchEvent(
        new CustomEvent('navigate', { detail: 'Alerts' })
      )
    },
    {
      icon:     '💚',
      label:    'System Status',
      value:    wsConnected ? 'Healthy' : 'Offline',
      sub:      wsConnected ? 'All Systems Operational' : 'Reconnecting...',
      subColor: '#64748b',
      valColor: wsConnected ? '#22c55e' : '#f97316',
      onClick:  null
    },
  ];

  return (
    <>
      <div style={{
        display:             'grid',
        gridTemplateColumns: 'repeat(4,1fr) auto',
        borderBottom:        '1px solid #1e2d47',
        flexShrink:          0,
        gap:                 '1px',
        background:          '#1e2d47'
      }}>
        {/* Stat cards */}
        {items.map((s, i) => (
          <div key={i} style={{
            background: '#111827',
            padding:    '10px 14px',
            display:    'flex',
            alignItems: 'center',
            gap:        12
          }}>
            <span style={{ fontSize: 24 }}>{s.icon}</span>
            <div>
              <div style={{ fontSize: 10, color: '#64748b' }}>
                {s.label}
              </div>
              <AnimatedNumber
                value={s.value}
                color={s.valColor || '#fff'}
              />
              <div
                style={{
                  fontSize:   10,
                  color:      s.subColor,
                  marginTop:  2,
                  cursor:     s.onClick ? 'pointer' : 'default',
                  fontWeight: s.onClick ? 600 : 400,
                  transition: 'color .15s'
                }}
                onClick={s.onClick || undefined}
                onMouseEnter={e => {
                  if (s.onClick) e.currentTarget.style.color = '#fff';
                }}
                onMouseLeave={e => {
                  if (s.onClick) e.currentTarget.style.color = s.subColor;
                }}
              >
                {s.sub}
              </div>
            </div>
          </div>
        ))}

        {/* Add Camera card — 5th column, matches the blue button in the image */}
        <div style={{
          background:     '#111827',
          padding:        '10px 14px',
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center',
        }}>
          <button
            onClick={() => setShowModal(true)}
            style={{
              background:   '#3b82f6',
              color:        '#fff',
              border:       'none',
              padding:      '7px 14px',
              borderRadius: 6,
              fontSize:     11,
              fontWeight:   600,
              cursor:       'pointer',
              display:      'flex',
              alignItems:   'center',
              gap:          4,
              whiteSpace:   'nowrap',
              transition:   'background .15s'
            }}
            onMouseEnter={e => e.currentTarget.style.background = '#2563eb'}
            onMouseLeave={e => e.currentTarget.style.background = '#3b82f6'}
          >
            + Add Camera
          </button>
        </div>
      </div>

      {showModal && (
        <AddCameraModal onClose={() => setShowModal(false)} />
      )}
    </>
  );
}
